<script setup lang="ts">
import { computed,onMounted,onBeforeUnmount,ref,watch } from 'vue'
import { onBeforeRouteLeave } from 'vue-router'
import { api } from '../../lib/api'
import { useAuthStore } from '../../stores/auth'
import MonsterStatblock from './MonsterStatblock.vue'
import MonsterActionEditor from './MonsterActionEditor.vue'
import { MONSTER_ABILITIES,monsterSigned,monsterModifier,monsterChallenge } from '../../../shared/monster-statblock'
import { MONSTER_STEPS,MONSTER_SECTIONS,SKILL_ABILITIES,newMonsterDraft,newMonsterAction,compileMonster,monsterDraftIssues,monsterPB,monsterHP,monsterAC,monsterHitDice,actionDescription,type MonsterDraft,type MonsterAction,type MonsterStep,type SavedMonsterAction } from '../../../shared/monster-workshop'
import { exportMonsterMarkdown,exportMonsterImage,printMonster } from '../../lib/monster-export'
import './monster-workshop.css'
type Pack={id:string;filename:string;hash:string;includeDisabled:boolean}
type Library={packs:Pack[];monsters:MonsterDraft[];actions:SavedMonsterAction[];warnings:string[]}
const auth=useAuthStore(),storageKey=`codex:monster-workshop:v1:${auth.user?.id??'local'}`
const library=ref<Library>({packs:[],monsters:[],actions:[],warnings:[]}),draft=ref<MonsterDraft|null>(null),drafts=ref<MonsterDraft[]>([]),step=ref<MonsterStep>('identity'),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),storageError=ref(''),selectedRule=ref(''),target=ref('new'),newPack=ref('My Bestiary.orcbrew'),query=ref(''),libraryOpen=ref(false),actionEditing=ref<MonsterAction|null>(null),editingSaved=ref<SavedMonsterAction|null>(null),libraryQuery=ref('')
const fallback=newMonsterDraft();fallback.name='Example creature';fallback.scores.str=16
const context=computed(()=>draft.value??fallback),statblock=computed(()=>compileMonster(context.value)),issues=computed(()=>draft.value?monsterDraftIssues(draft.value):[]),rule=computed(()=>draft.value?.rules.find(r=>r.id===selectedRule.value)??null),libraryMatches=computed(()=>library.value.actions.filter(a=>`${a.action.name} ${a.action.section}`.toLowerCase().includes(libraryQuery.value.toLowerCase()))),monsters=computed(()=>library.value.monsters.filter(m=>`${m.name} ${m.source}`.toLowerCase().includes(query.value.toLowerCase())))
const copy=<T,>(value:T):T=>JSON.parse(JSON.stringify(value))
let timer:ReturnType<typeof setTimeout>|undefined
function persist(){if(!draft.value)return true;const value=copy(draft.value),next=[value,...drafts.value.filter(d=>d.id!==value.id)];try{localStorage.setItem(storageKey,JSON.stringify(next));drafts.value=next;storageError.value='';return true}catch{storageError.value='The browser could not save this draft. Keep the page open and download a backup before leaving.';return false}}
watch(draft,()=>{notice.value='';clearTimeout(timer);timer=setTimeout(persist,600)},{deep:true})
function flush(){clearTimeout(timer);return persist()}
defineExpose({persist:()=>!busy.value&&flush()})
function unload(event:BeforeUnloadEvent){if(!flush())event.preventDefault()}
onBeforeRouteLeave(()=>!busy.value&&flush())
onBeforeUnmount(()=>{flush();window.removeEventListener('beforeunload',unload)})
async function load(){loading.value=true;error.value='';try{library.value=await api.get('/api/monster-workshop/library',{timeoutMs:60000})}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
onMounted(()=>{try{const saved=JSON.parse(localStorage.getItem(storageKey)??'[]');if(Array.isArray(saved))drafts.value=saved.filter(d=>d?.version===1&&typeof d.id==='string'&&d.scores&&d.armor&&d.hp&&Array.isArray(d.rules)&&d.introductions&&d.endNotes)}catch{storageError.value='Device drafts could not be read; their original data has been kept.'}window.addEventListener('beforeunload',unload);load()})
function open(value:MonsterDraft){if(!flush())return;draft.value=copy(value);step.value='identity';selectedRule.value=value.rules[0]?.id??'';target.value=value.published?.packId??'new';newPack.value=(value.source||'My Bestiary').replace(/[<>:"/\\|?*]/g,'-')+'.orcbrew';libraryOpen.value=false;actionEditing.value=null;error.value='';window.scrollTo({top:0})}
function back(){if(flush()){draft.value=null;libraryOpen.value=false;actionEditing.value=null;error.value=''}}
function go(value:MonsterStep){step.value=value;libraryOpen.value=false;actionEditing.value=null}
function addRule(){if(!draft.value)return;const next=newMonsterAction();draft.value.rules.push(next);selectedRule.value=next.id}
function addSpellcasting(){if(!draft.value)return;const next=newMonsterAction('traits');next.name='Spellcasting';next.description='[MON] uses Intelligence for spellcasting (spell save DC [INT SAVE], [INT ATK] to hit).\nAt will: list spells here.\n1/day each: list spells here.';draft.value.rules.push(next);selectedRule.value=next.id}
function removeRule(){if(!draft.value||!rule.value)return;const index=draft.value.rules.indexOf(rule.value);draft.value.rules.splice(index,1);selectedRule.value=draft.value.rules[Math.min(index,draft.value.rules.length-1)]?.id??''}
function moveRule(direction:number){if(!draft.value||!rule.value)return;const list=draft.value.rules,index=list.indexOf(rule.value),next=index+direction;if(next<0||next>=list.length)return;[list[index],list[next]]=[list[next]!,list[index]!]}
function insert(saved:SavedMonsterAction){if(!draft.value)return;const action=copy(saved.action);action.id=crypto.randomUUID();action.librarySource={id:saved.id,revision:saved.revision};draft.value.rules.push(action);selectedRule.value=action.id;libraryOpen.value=false;actionEditing.value=null;notice.value='Action copied to this monster. Later library edits will not change this copy.'}
function editAction(saved?:SavedMonsterAction){editingSaved.value=saved??null;actionEditing.value=copy(saved?.action??newMonsterAction());libraryOpen.value=true}
async function saveAction(value:MonsterAction,existing:SavedMonsterAction|null=null){if(busy.value)return;busy.value=true;error.value='';try{const saved=existing?await api.put<SavedMonsterAction>(`/api/monster-workshop/actions/${existing.id}`,{action:value,revision:existing.revision}):await api.post<SavedMonsterAction>('/api/monster-workshop/actions',{action:value});library.value.actions=[saved,...library.value.actions.filter(a=>a.id!==saved.id)];actionEditing.value=null;editingSaved.value=null;libraryOpen.value=true;notice.value='Action saved to your account library. Existing monster copies are unchanged.'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function publish(){if(!draft.value||issues.value.length||busy.value)return;if(!flush())return;busy.value=true;error.value='';const originalId=draft.value.id;try{const pack=library.value.packs.find(p=>p.id===target.value);if(target.value!=='new'&&!pack)throw new Error('The selected pack is unavailable. Reload the library or choose a new pack.');const result=await api.post<{draft:MonsterDraft;message:string}>('/api/monster-workshop/publish',{draft:draft.value,target:pack?{packId:pack.id,hash:pack.hash}:{filename:newPack.value}});drafts.value=drafts.value.filter(d=>d.id!==originalId);try{localStorage.setItem(storageKey,JSON.stringify(drafts.value))}catch{/* The saved account definition remains safe; persist reports device errors. */}draft.value=result.draft;target.value=result.draft.published!.packId;persist();await load();notice.value=result.message;step.value='review'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function download(name:string,body:string,type:string){const url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const exportName=()=>context.value.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')||'monster'
async function orcbrew(){if(!draft.value||issues.value.length||busy.value)return;busy.value=true;error.value='';try{const file=await api.post<{filename:string;source:string}>('/api/monster-workshop/export',{draft:draft.value});download(file.filename,file.source,'application/octet-stream')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function backup(){if(busy.value)return;flush();busy.value=true;error.value='';try{const data=await api.get<Record<string,unknown>>('/api/workshop/backup',{timeoutMs:60000});data.device={monsterDrafts:drafts.value,workshopDrafts:JSON.parse(localStorage.getItem(`codex:homebrew-workshop:v1:${auth.user?.id??'local'}`)??'[]'),characterDraft:JSON.parse(localStorage.getItem(`codex:character-builder:v1:${auth.user?.id??'local'}`)??'null'),appearance:JSON.parse(localStorage.getItem('codex:builder-appearance:v1')??'null')};download('codex-of-heroes-backup.json',JSON.stringify(data,null,2),'application/json');notice.value='Complete account backup downloaded, including saved monsters, actions and device monster drafts.'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function image(){error.value='';try{await exportMonsterImage(statblock.value,exportName()+'.png')}catch(e){error.value=(e as Error).message}}
function markdown(){download(exportName()+'.md',exportMonsterMarkdown(statblock.value),'text/markdown')}
const reader=ref<HTMLElement|null>(null)
function print(){try{printMonster(reader.value)}catch(e){error.value=(e as Error).message}}
function optionalNumber(event:Event,set:(value:number|null)=>void){const v=(event.target as HTMLInputElement).value;set(v===''?null:Number(v))}
const remainingSections=MONSTER_SECTIONS.filter(s=>!['traits','actions','bonus-actions','reactions'].includes(s.key))
</script>
<template>
<section class="monster-workshop">
  <header class="mw-header"><div><h2>Monster Workshop</h2><p class="hw-hint">{{draft?'Build in sections. Click a statblock section to edit its rules.':'Create monsters and reusable actions for your bestiary.'}}</p></div><div class="hw-actions"><button v-if="draft" class="hw-button" :disabled="busy" @click="back">Back to library</button><button v-if="draft" class="hw-button" @click="flush()&&(notice='Draft saved on this device.')">Save draft</button><button v-if="draft" class="hw-button hw-button-primary" @click="go('review')">Review &amp; save</button><template v-else><button class="hw-button" @click="libraryOpen=!libraryOpen;actionEditing=null">Action library</button><button class="hw-button hw-button-primary" @click="open(newMonsterDraft())">+ Create monster</button></template></div></header>
  <p v-if="error" class="hw-alert" role="alert">{{error}} <button v-if="!busy" class="hw-text-button" @click="load">Reload library</button></p><p v-if="storageError" class="hw-alert" role="alert">{{storageError}}</p><p v-if="notice" class="hw-save-status" role="status">{{notice}}</p>
  <template v-if="draft">
  <fieldset class="mw-workspace" :disabled="busy" aria-label="Monster creation workspace">
    <nav class="mw-steps" aria-label="Monster creation sections"><button v-for="([key,label],i) in MONSTER_STEPS" :key="key" :aria-current="step===key?'step':undefined" @click="go(key)"><span>{{i+1}}</span>{{label}}</button><p class="hw-hint">Drafts stay on this device. Save to a pack to make the creature available in your account.</p></nav>
    <section class="mw-editor" aria-label="Monster editor">
      <template v-if="libraryOpen"><div class="mw-between"><h3>Action library</h3><button class="hw-text-button" @click="libraryOpen=false;actionEditing=null">Back to creature</button></div><p class="hw-hint">Adding an action makes an independent copy. Revised library actions affect future additions only.</p>
      <label>Find an action<input v-model="libraryQuery" type="search"></label><div v-for="a in libraryMatches" :key="a.id" class="mw-library-row"><div><strong>{{a.action.name}}</strong><small>{{MONSTER_SECTIONS.find(s=>s.key===a.action.section)?.name}} · revision {{a.revision+1}}</small><p>{{actionDescription(draft,a.action)}}</p></div><div class="hw-actions"><button class="hw-button" @click="editAction(a)">Edit saved action</button><button class="hw-button hw-button-primary" :disabled="busy||draft.rules.length>=150" @click="insert(a)">Add to creature</button></div></div><p v-if="!libraryMatches.length" class="hw-hint">No saved actions match. Create an action below, or save one from this creature.</p><button class="hw-button" @click="editAction()">+ Create reusable action</button><template v-if="actionEditing"><h3>{{editingSaved?'Edit saved action':'New reusable action'}}</h3><MonsterActionEditor :rule="actionEditing" :monster="draft"/><button class="hw-button hw-button-primary" :disabled="busy" @click="saveAction(actionEditing,editingSaved)">Save action to library</button></template></template>
      <template v-else-if="step==='identity'"><h3>Creature</h3><div class="mw-fields"><label class="mw-full">Name<input v-model="draft.name" maxlength="250"></label><label>Size<select v-model="draft.size"><option>Tiny</option><option>Small</option><option>Medium</option><option>Large</option><option>Huge</option><option>Gargantuan</option></select></label><label>Creature type<input v-model="draft.type" list="mw-types" maxlength="250"><datalist id="mw-types"><option v-for="t in ['aberration','beast','celestial','construct','dragon','elemental','fey','fiend','giant','humanoid','monstrosity','ooze','plant','undead']" :key="t">{{t}}</option></datalist></label><label>Subtype / tag<input v-model="draft.subtype" maxlength="250"></label><label>Alignment<input v-model="draft.alignment" maxlength="250"></label><label>Short name in rules<input v-model="draft.shortName" maxlength="250"></label><label>Plural name in rules<input v-model="draft.plural" maxlength="250"></label><label class="mw-full">Source collection<input v-model="draft.source" maxlength="250"></label><label class="mw-full">Description / lore<textarea v-model="draft.description" rows="4" maxlength="20000"></textarea></label></div></template>
      <template v-else-if="step==='statistics'"><h3>Statistics</h3><div class="mw-abilities"><label v-for="a in MONSTER_ABILITIES" :key="a">{{a.toUpperCase()}}<input v-model.number="draft.scores[a]" type="number" min="1" max="50"><small>{{monsterSigned(monsterModifier(draft.scores[a]))}}</small></label></div><div class="mw-fields"><label>Challenge rating<select v-model.number="draft.cr"><option v-for="cr in [0,0.125,0.25,0.5,...Array.from({length:30},(_,i)=>i+1)]" :key="cr" :value="cr">{{monsterChallenge(cr)}}</option></select></label><label>XP (optional)<input :value="draft.xp??''" type="number" min="0" max="1000000000" @input="optionalNumber($event,v=>draft!.xp=v)"></label><label>Custom challenge text<input v-model="draft.crText" placeholder="Blank uses the numeric CR" maxlength="250"></label><label>Proficiency bonus override<input :value="draft.pbOverride??''" type="number" min="0" max="20" :placeholder="String(monsterPB(draft))" @input="optionalNumber($event,v=>draft!.pbOverride=v)"></label></div><p class="hw-hint">Blank overrides use calculated values. CR is chosen by you, not an automatic assessment of encounter balance.</p><h3>Hit points</h3><div class="mw-fields"><label>Hit dice count<input v-model.number="draft.hp.count" type="number" min="1" max="999"></label><label>Die size<select v-model.number="draft.hp.die"><option v-for="die in [4,6,8,10,12,20]" :key="die" :value="die">d{{die}}</option></select></label></div><label class="mw-check"><input v-model="draft.hp.useCon" type="checkbox">Use CON modifier for each hit die</label><div class="mw-fields"><label>Custom dice modifier<input v-model.number="draft.hp.modifier" :disabled="draft.hp.useCon" type="number" min="-100000" max="100000"></label><label>Override average HP (optional)<input :value="draft.hp.override??''" type="number" min="1" max="10000000" @input="optionalNumber($event,v=>draft!.hp.override=v)"></label></div><p class="mw-calculation">{{monsterHP(draft)}} HP <span>({{monsterHitDice(draft)}})</span></p></template>
      <template v-else-if="step==='defenses'"><h3>Defenses &amp; movement</h3><div class="mw-fields"><label>Armor calculation<select v-model="draft.armor.mode"><option value="unarmored">Unarmored (10 + DEX)</option><option value="natural">Natural armor</option><option value="leather">Leather armor (11 + DEX)</option><option value="scale">Scale mail (14 + DEX, max 2)</option><option value="plate">Plate armor (18)</option><option value="custom">Custom AC</option></select></label><label v-if="['natural','custom'].includes(draft.armor.mode)">Base AC<input v-model.number="draft.armor.base" type="number" min="0" max="100"></label></div><template v-if="draft.armor.mode==='natural'"><label class="mw-check"><input v-model="draft.armor.dex" type="checkbox">Add DEX modifier</label><label>DEX cap (optional)<input :value="draft.armor.dexCap??''" type="number" min="0" max="20" @input="optionalNumber($event,v=>draft!.armor.dexCap=v)"></label></template><label class="mw-check"><input v-model="draft.armor.shield" type="checkbox">Add a shield (+2 AC)</label><label>Armor note<input v-model="draft.armor.note" maxlength="250" placeholder="Blank uses the selected armor description"></label><p class="mw-calculation">Armor Class {{monsterAC(draft)}}</p><div class="mw-fields"><label v-for="key in (['walk','burrow','climb','fly','swim'] as const)" :key="key">{{key}} speed (ft.)<input v-model.number="draft.movement[key]" type="number" min="0" max="100000"></label><label>Custom movement description<input v-model="draft.movement.custom" maxlength="2000" placeholder="Overrides the speed list"></label></div><label class="mw-check"><input v-model="draft.movement.hover" type="checkbox">Can hover while flying</label><details><summary>Saving throws &amp; skill proficiencies</summary><div class="mw-checks"><label v-for="a in MONSTER_ABILITIES" :key="a" class="mw-check"><input v-model="draft.saves" :value="a" type="checkbox">{{a.toUpperCase()}}</label></div><div class="mw-fields"><label v-for="name in Object.keys(SKILL_ABILITIES)" :key="name">{{name}}<select v-model.number="draft.skills[name]"><option :value="0">Not proficient</option><option :value="1">Proficient</option><option :value="2">Expertise</option></select></label></div><details><summary>Fixed save and skill bonuses</summary><div class="mw-fields"><label v-for="a in MONSTER_ABILITIES" :key="a">{{a.toUpperCase()}} save override<input :value="draft.saveOverrides[a]??''" type="number" min="-100" max="100" @input="optionalNumber($event,v=>v===null?delete draft!.saveOverrides[a]:draft!.saveOverrides[a]=v)"></label><label v-for="name in Object.keys(draft.skills).filter(n=>draft!.skills[n])" :key="name">{{name}} override<input :value="draft.skillOverrides[name]??''" type="number" min="-100" max="100" @input="optionalNumber($event,v=>v===null?delete draft!.skillOverrides[name]:draft!.skillOverrides[name]=v)"></label></div></details></details><h3>Resistances &amp; immunities</h3><div class="mw-fields"><label>Damage vulnerabilities<input v-model="draft.vulnerabilities" maxlength="2000"></label><label>Damage resistances<input v-model="draft.resistances" maxlength="2000" placeholder="Include conditions, such as nonmagical attacks"></label><label>Damage immunities<input v-model="draft.damageImmunities" maxlength="2000"></label><label>Condition immunities<input v-model="draft.conditionImmunities" maxlength="2000"></label></div><details><summary>Senses &amp; languages</summary><div class="mw-fields"><label v-for="key in (['blindsight','darkvision','tremorsense','truesight'] as const)" :key="key">{{key}} (ft.)<input v-model.number="draft.senses[key]" type="number" min="0" max="100000"></label><label>Passive Perception override<input :value="draft.passiveOverride??''" type="number" min="-100" max="100" @input="optionalNumber($event,v=>draft!.passiveOverride=v)"></label><label>Telepathy (ft.)<input v-model.number="draft.telepathy" type="number" min="0" max="100000"></label><label class="mw-full">Languages<input v-model="draft.languages" maxlength="2000"></label></div><label class="mw-check"><input v-model="draft.senses.blindBeyond" type="checkbox">Blind beyond blindsight radius</label><label class="mw-check"><input v-model="draft.understandsOnly" type="checkbox">Understands these languages but cannot speak</label></details></template>
      <template v-else-if="step==='rules'"><h3>Traits &amp; actions</h3><div class="mw-library-toolbar"><button class="hw-button" @click="libraryOpen=true;actionEditing=null">From action library</button><span class="hw-hint">Insert a copy from your saved actions.</span></div><label v-if="draft.rules.length">Editing rule<select v-model="selectedRule"><option v-for="r in draft.rules" :key="r.id" :value="r.id">{{r.name||'Unnamed rule'}} · {{MONSTER_SECTIONS.find(s=>s.key===r.section)?.name}}</option></select></label><div class="hw-actions"><button class="hw-button" :disabled="draft.rules.length>=150" @click="addRule">+ Add rule</button><button class="hw-text-button" :disabled="draft.rules.length>=150" @click="addSpellcasting">Add spellcasting template</button></div><template v-if="rule"><MonsterActionEditor :rule="rule" :monster="draft"/><div class="hw-actions"><button class="hw-button" :disabled="busy" @click="saveAction(rule)">Save this action to library</button><button class="hw-button" :disabled="draft.rules[0]?.id===rule.id" @click="moveRule(-1)">Move up</button><button class="hw-button" :disabled="draft.rules.at(-1)?.id===rule.id" @click="moveRule(1)">Move down</button><button class="hw-text-button" @click="removeRule">Remove from creature</button></div><p v-if="rule.librarySource" class="hw-hint">Independent copy of library revision {{rule.librarySource.revision+1}}. Later library edits do not change this monster.</p></template><p v-else class="hw-hint">Add a trait, attack, bonus action, reaction or another rule to begin.</p></template>
      <template v-else-if="step==='advanced'"><h3>Advanced rules</h3><p class="hw-hint">Optional introductions and end notes for legendary, mythic, lair and regional rules. Add the individual actions under Traits &amp; actions.</p><details v-for="s in remainingSections" :key="s.key"><summary>{{s.name}}</summary><label>Introduction<textarea v-model="draft.introductions[s.key]" rows="4" maxlength="20000"></textarea></label><label>End note<textarea v-model="draft.endNotes[s.key]" rows="3" maxlength="20000"></textarea></label></details><p class="hw-hint">Written rules do not automatically execute combat effects, targeting or dice rolls.</p></template>
      <template v-else><h3>Review &amp; save</h3><p v-if="issues.length" class="hw-alert" role="alert">Resolve these details before saving:</p><button v-for="(issue,i) in issues" :key="i" class="mw-issue" @click="go(issue.step)">{{issue.message}}</button><p v-if="!issues.length" class="hw-callout">Required details complete. Review the full statblock before saving. Challenge rating is your choice, not an automatic balance assessment.</p><div v-for="[key,label] in MONSTER_STEPS.filter(s=>s[0]!=='review')" :key="key" class="mw-review-row"><div><strong>{{label}}</strong><small v-if="key==='identity'">{{draft.name}} · {{draft.size}} {{draft.type}}</small><small v-else-if="key==='statistics'">{{monsterHP(draft)}} HP · AC {{monsterAC(draft)}} · CR {{monsterChallenge(draft.cr)}} · proficiency {{monsterSigned(monsterPB(draft))}}</small><small v-else-if="key==='rules'">{{draft.rules.length}} rules; {{draft.rules.filter(r=>r.librarySource).length}} independent library copies</small></div><button class="hw-text-button" @click="go(key)">Edit</button></div><label>Save to pack<select v-model="target"><option value="new">Create a new pack</option><option v-for="p in library.packs" :key="p.id" :value="p.id">{{p.filename}}</option></select></label><label v-if="target==='new'">New pack filename<input v-model="newPack" maxlength="255" placeholder="My Bestiary.orcbrew"></label><p v-if="draft.published&&draft.published.packId!==target" class="hw-hint">Choosing another pack saves a separate creature copy. The original stays in its pack.</p><button class="hw-button hw-button-primary" :disabled="busy||issues.length>0||loading" @click="publish">{{busy?'Saving…':'Save monster to pack'}}</button><details><summary>Export &amp; presentation</summary><label>Statblock columns<select v-model="draft.presentation"><option value="one">One column</option><option value="two">Two columns when printing</option></select></label><div class="hw-actions"><button class="hw-button" :disabled="busy||issues.length>0" @click="orcbrew">Export Orcbrew</button><button class="hw-button" @click="markdown">Markdown</button><button class="hw-button" @click="image">PNG image</button><button class="hw-button" @click="print">Print</button><button class="hw-button" :disabled="busy" @click="backup">Complete account backup</button></div></details></template>
      <footer v-if="step!=='review'&&!libraryOpen" class="mw-footer"><button class="hw-button" :disabled="step==='identity'" @click="go(MONSTER_STEPS[Math.max(0,MONSTER_STEPS.findIndex(s=>s[0]===step)-1)]![0])">Back</button><button class="hw-button hw-button-primary" @click="go(MONSTER_STEPS[Math.min(5,MONSTER_STEPS.findIndex(s=>s[0]===step)+1)]![0])">{{step==='advanced'?'Review monster':'Continue'}}</button></footer>
    </section>
    <aside class="mw-preview" aria-label="Live monster preview"><p class="hw-hint">Click a section to edit. Scroll for the full statblock.</p><div ref="reader" class="mw-preview-scroll" :class="{'mw-two-columns':draft.presentation==='two'}"><MonsterStatblock :monster="statblock" editable @edit="go"/></div></aside>
  </fieldset></template>
  <template v-else-if="libraryOpen"><fieldset class="mw-editor" :disabled="busy"><div class="mw-between"><h3>Reusable action library</h3><button class="hw-button" @click="editAction()">+ Create reusable action</button></div><p class="hw-hint">Saved to your account. Changes apply when you add the revised action again; existing monsters keep their copies.</p><label>Find an action<input v-model="libraryQuery" type="search"></label><div v-for="a in libraryMatches" :key="a.id" class="mw-library-row"><div><strong>{{a.action.name}}</strong><small>{{MONSTER_SECTIONS.find(s=>s.key===a.action.section)?.name}} · revision {{a.revision+1}}</small></div><button class="hw-button" @click="editAction(a)">Edit action</button></div><p v-if="!loading&&!libraryMatches.length" class="hw-hint">No saved actions match. Create one above, or save an action while making a monster.</p><template v-if="actionEditing"><MonsterActionEditor :rule="actionEditing" :monster="fallback"/><p class="hw-hint">Calculation example only: ability scores 10, STR 16, proficiency +2. Adding this action to a monster uses that monster's actual values.</p><button class="hw-button hw-button-primary" :disabled="busy" @click="saveAction(actionEditing,editingSaved)">Save reusable action</button></template></fieldset></template>
  <template v-else><div class="mw-library-top"><label>Find my monsters<input v-model="query" type="search"></label><button class="hw-button" :disabled="loading" @click="load">Reload library</button><button class="hw-button" :disabled="busy" @click="backup">Download account backup</button></div><p v-if="loading" class="hw-hint" role="status">Loading your saved bestiary… You can start a new monster now.</p><section v-if="drafts.length"><h3>Device drafts</h3><div class="mw-cards"><button v-for="d in drafts" :key="d.id" class="mw-card" @click="open(d)"><strong>{{d.name||'Untitled monster'}}</strong><span>{{d.source}} · Continue draft</span></button></div></section><h3>Saved monsters</h3><p v-if="!loading&&!monsters.length" class="hw-hint">Create your first monster above. Imported creatures remain readable in the Compendium; adaptation is a separate future feature.</p><div class="mw-cards"><button v-for="d in monsters" :key="d.id+':'+d.published?.packId" class="mw-card" @click="open(d)"><strong>{{d.name}}</strong><span>{{d.size}} {{d.type}} · CR {{monsterChallenge(d.cr)}} · {{d.source}}</span><span>Open saved revision {{d.published?.revision}}</span></button></div><p v-for="warning in library.warnings" :key="warning" class="hw-alert">{{warning}}</p></template>
</section>
</template>
